const detailMapElement=document.querySelector('#detail-map');
if(detailMapElement&&window.L){const lat=Number(detailMapElement.dataset.lat),lng=Number(detailMapElement.dataset.lng),title=detailMapElement.dataset.title;const detailMap=L.map(detailMapElement,{scrollWheelZoom:false}).setView([lat,lng],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(detailMap);const icon=L.divIcon({className:'',html:'<span class="map-pin"></span>',iconSize:[38,38],iconAnchor:[19,19]});L.marker([lat,lng],{icon,title}).addTo(detailMap)}else if(detailMapElement){detailMapElement.textContent='Carte momentanément indisponible.'}
